def authority_sources(helper):
    result = {}
    for name, digest in AUTHORITY_FILES.items():
        path = ROOT.parents[3] / name
        helper.reject_links(path)
        if path.stat().st_size > 65536:
            fail('authority_size')
        data = helper.read_regular(path)
        if sha(data) != digest:
            fail('authority_identity')
        result[name] = data
    return result
